import re, unicodedata
def norm(s):
    s = unicodedata.normalize('NFC', s)
    for q in '“”″': s = s.replace(q, '"')
    for q in '‘’': s = s.replace(q, "'")
    s = re.sub(r'- \d+ -', '', s)
    s = re.sub(r'\s+', ' ', s).strip()
    return s
src = open('입력_원문.md', encoding='utf-8').read()
# per-block
blocks = {}
cur=None
for line in src.splitlines():
    m = re.match(r'### (조:\S+)', line)
    if m: cur=m.group(1); blocks[cur]=[]; continue
    if cur: blocks[cur].append(line)
blocks = {k: norm('\n'.join(v)) for k,v in blocks.items()}
out = open('추출_B.md', encoding='utf-8').read()
ob = {}
cur=None
for line in out.splitlines():
    m = re.match(r'### (조:\S+)', line)
    if m: cur=m.group(1); ob[cur]=[]; continue
    if cur: ob[cur].append(line)
print('input ids', len(blocks), 'output ids', len(ob))
print('missing', set(blocks)-set(ob), 'extra', set(ob)-set(blocks))
bad=0
for k, lines in ob.items():
    for line in lines:
        if line.startswith('원문:'): continue
        for ex in re.findall(r'"([^"]*)"', line):
            e = norm(ex)
            if e not in blocks.get(k,''):
                bad+=1; print('BAD', k, '|', ex[:90])
        # 문장 checks
        for seg in line.split(' | '):
            if seg.strip().startswith('문장 '):
                if '"' in seg or '규범:' in seg: print('문장issue', k, seg[:60])
print('bad', bad)
